@startuml

class Driver {
  + ID : int
  + Name : string
  + IsOnSickLeave : boolean
}

class Bus {
  + LicensePlate : string
  + IsInRepairShop : boolean
}

class Route {
  + RouteNumber : int
}

class Shift {
  + ShiftType : ShiftType
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

class Schedule {
  + Date : date
}

Driver "1" -- "*" Schedule
Bus "1" -- "*" Schedule
Route "1" -- "*" Schedule
Schedule "*" -- "1" Shift

@enduml

